      const theo = lines.map((l) => ({ component: l.component, itemId: l.itemId, kgMilli: Math.round((l.qtyMilli * qty) / 1000) })); const act = b.weights.map((w) => ({ component: w.component, itemId: lines.find((l) => l.component === w.component)?.itemId ?? null, kgMilli: e3(w.kg) }));
