    options(actor, q = {}) { gate(actor, 'rmc.delivery_ticket.create', 'make delivery tickets'); void q; return { requisitions: db.prepare("SELECT id, doc_no AS docNo, grade, qty_milli AS qtyMilli, plant_id AS plantId, supplier_id AS supplierId, org_project_id AS projectId, required_at AS requiredAt FROM bp_requisitions WHERE company_id = ? AND deleted_at IS NULL AND status = 'APPROVED' AND prod_status IN ('SCHEDULED', 'IN_PROGRESS') ORDER BY required_at").all(actor.companyId).filter((r) => may(actor, 'rmc.delivery_ticket.view', r.projectId)).map((r) => ({ id: r.id, docNo: r.docNo, grade: r.grade, qty: f3(r.qtyMilli), plantId: r.plantId, supplierId: r.supplierId, requiredAt: r.requiredAt, supplier: partnerName(r.supplierId), plant: r.plantId ? plants.currentRow(r.plantId)?.code : null })), batches: db.prepare("SELECT id, doc_no AS docNo, plant_id AS plantId, requisition_id AS requisitionId, qty_milli AS qtyMilli, batch_time AS batchTime FROM bp_batches WHERE company_id = ? AND deleted_at IS NULL AND batch_status = 'ACTIVE' ORDER BY id DESC LIMIT 200").all(actor.companyId).map((x) => ({ id: x.id, docNo: x.docNo, plantId: x.plantId, requisitionId: x.requisitionId, qty: f3(x.qtyMilli), batchTime: x.batchTime })), eway: param(actor.companyId, 'rmc.eway.required') !== false }; },
